-- Phase 7: additive columns only. Existing RLS policies remain unchanged.
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS business_type text;
ALTER TABLE public.purchases ADD COLUMN IF NOT EXISTS category text;


create or replace function public.save_jobflow_business_type(p_type text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare result jsonb; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_type not in ('electrician','plumber','ac-appliance-repair','carpenter','painting-waterproofing','home-cleaning','pest-control','packers-movers','cctv-security','solar-installation','salon','catering','bakery','photography','wedding-planner','gym-fitness','tailoring','web-development','digital-marketing','graphic-design','signage-boards','printing-packaging','interior-designer','tutoring','mobile-repair','car-detailing','other') or p_type is null then raise exception 'Invalid business type'; end if; update public.profiles set business_type=p_type where id=auth.uid() and role='owner' returning jsonb_build_object('id',id,'role',role,'business_type',business_type) into result; if result is null then raise exception 'Owner profile required'; end if; return result; end $$; revoke all on function public.save_jobflow_business_type(text) from public,anon; grant execute on function public.save_jobflow_business_type(text) to authenticated;
